import * as React from "react"
import { createStore } from "zustand"

import { createContextStore } from "@/lib/context-store"
import type { PermissionCheck } from "@/lib/user-access"
import type { IconProp } from "@/components/forge/icons"

/* -------------------------------------------------------------------------- */
/* Config                                                                     */
/* -------------------------------------------------------------------------- */

/** An entry in the icon rail or the sidebar. */
export type ShellNavItem = {
  id: string
  label: string
  icon?: IconProp
  /** Where it goes. Active automatically when it matches the current path. */
  href?: string
  /** Runs on click (as well as navigating to `href`). */
  onSelect?: () => void
  /** Trailing sidebar detail: a count, a dot, a chevron. */
  meta?: React.ReactNode
  /** Nested entries (sidebar only), shown as a sub-list. */
  items?: ShellNavItem[]
  /** Hidden unless the user has it (needs `UserAccessProvider`). */
  permission?: PermissionCheck
  /** Hidden unless the user has this role (needs `UserAccessProvider`). */
  role?: string
}

export type ShellNavSection = {
  id: string
  /** The section heading; omit for an untitled group. */
  title?: string
  /** Trailing heading control, e.g. an add button. */
  action?: React.ReactNode
  /** `primary` for the top block (padded, divided); `flush` for the last. */
  variant?: "default" | "primary" | "flush"
  items: ShellNavItem[]
}

export type ShellCrumb = {
  id?: string
  label: string
  icon?: IconProp
  href?: string
  onSelect?: () => void
}

export type ShellRail = {
  items: ShellNavItem[]
  /** Pinned to the bottom of the rail (settings, help…). */
  footer: ShellNavItem[]
}

export type ShellSidebar = {
  /** Hide the sub nav entirely (e.g. a full-width dashboard). */
  hidden: boolean
  /** The sidebar's accessible name (and the mobile sheet's title). */
  label?: string
  sections: ShellNavSection[]
}

export type ShellHeader = {
  /** The page name in the top bar (its h1). */
  title?: string
  icon?: IconProp
  /** Crumbs before the title. */
  breadcrumbs: ShellCrumb[]
}

export type ShellActive = {
  /** Id of the active rail item; default: the one matching the path. */
  rail?: string
  /** Id of the active sidebar item; default: the one matching the path. */
  sidebar?: string
}

/** Any part of the shell. Later layers override earlier ones, key by key. */
export type ShellConfig = {
  rail?: Partial<ShellRail>
  sidebar?: Partial<ShellSidebar>
  header?: Partial<ShellHeader>
  active?: ShellActive
}

/** What the shell shows: every layer merged. */
export type ResolvedShell = {
  rail: ShellRail
  sidebar: ShellSidebar
  header: ShellHeader
  active: ShellActive
}

export type ShellSlotName =
  "header-actions" | "toolbar" | "footer" | "sidebar-top" | "sidebar-bottom"

const emptyShell: ResolvedShell = {
  rail: { items: [], footer: [] },
  sidebar: { hidden: false, sections: [] },
  header: { breadcrumbs: [] },
  active: {},
}

const defined = <T extends object>(value: T | undefined) =>
  value
    ? (Object.fromEntries(
        Object.entries(value).filter(([, entry]) => entry !== undefined)
      ) as Partial<T>)
    : {}

/** Merges configs in order; `undefined` values leave the earlier one. */
export function resolveShell(configs: readonly ShellConfig[]): ResolvedShell {
  return configs.reduce<ResolvedShell>(
    (shell, config) => ({
      rail: { ...shell.rail, ...defined(config.rail) },
      sidebar: { ...shell.sidebar, ...defined(config.sidebar) },
      header: { ...shell.header, ...defined(config.header) },
      active: { ...shell.active, ...defined(config.active) },
    }),
    emptyShell
  )
}

function patchItems(
  items: ShellNavItem[] | undefined,
  id: string,
  patch: Partial<ShellNavItem>
): ShellNavItem[] | undefined {
  return items?.map((item) =>
    item.id === id
      ? { ...item, ...patch }
      : item.items
        ? { ...item, items: patchItems(item.items, id, patch) }
        : item
  )
}

function patchConfig(
  config: ShellConfig,
  id: string,
  patch: Partial<ShellNavItem>
): ShellConfig {
  return {
    ...config,
    ...(config.rail && {
      rail: {
        ...config.rail,
        ...(config.rail.items && {
          items: patchItems(config.rail.items, id, patch),
        }),
        ...(config.rail.footer && {
          footer: patchItems(config.rail.footer, id, patch),
        }),
      },
    }),
    ...(config.sidebar?.sections && {
      sidebar: {
        ...config.sidebar,
        sections: config.sidebar.sections.map((section) => ({
          ...section,
          items: patchItems(section.items, id, patch) ?? [],
        })),
      },
    }),
  }
}

/* -------------------------------------------------------------------------- */
/* Store                                                                      */
/* -------------------------------------------------------------------------- */

type ShellLayer = { id: string; order: number; config: ShellConfig }

export type ShellLinkRenderer = (href: string) => React.ReactElement

export type ShellStoreState = {
  /** The initial config plus everything `configure` changed. */
  base: ShellConfig
  /** Page layers, in the order their components first rendered. */
  layers: ShellLayer[]
  /** The merged result the shell renders. */
  shell: ResolvedShell
  currentPath: string | undefined
  navigate: ((href: string) => void) | undefined
  renderLink: ShellLinkRenderer | undefined
  /** Slot targets by name; the last registered one is used. */
  slots: Partial<Record<ShellSlotName, HTMLElement[]>>
  /** Changes the base config (merged in, key by key). Persists across pages. */
  configure: (
    config: ShellConfig | ((shell: ResolvedShell) => ShellConfig)
  ) => void
  /** Marks items active, overriding path matching. */
  setActive: (active: ShellActive) => void
  /** Patches a rail or sidebar item by id, in every layer (counts, labels…). */
  updateItem: (id: string, patch: Partial<ShellNavItem>) => void
  /** Adds, replaces (keeping its place) or, with null, removes a page layer. */
  setLayer: (id: string, order: number, config: ShellConfig | null) => void
  /** A number for ordering layers: parents render before their children. */
  nextOrder: () => number
  registerSlot: (name: ShellSlotName, element: HTMLElement) => () => void
}

export type ShellStoreInit = {
  initial?: ShellConfig
  currentPath?: string
  navigate?: (href: string) => void
  renderLink?: ShellLinkRenderer
}

function createShellStore({
  initial = {},
  currentPath,
  navigate,
  renderLink,
}: ShellStoreInit) {
  let order = 0
  return createStore<ShellStoreState>()((set, get) => {
    const commit = (base: ShellConfig, layers: ShellLayer[]) =>
      set({
        base,
        layers,
        shell: resolveShell([base, ...layers.map((layer) => layer.config)]),
      })

    return {
      base: initial,
      layers: [],
      shell: resolveShell([initial]),
      currentPath,
      navigate,
      renderLink,
      slots: {},
      configure: (config) => {
        const { base, layers, shell } = get()
        const next = typeof config === "function" ? config(shell) : config
        commit(resolveShellConfig(base, next), layers)
      },
      setActive: (active) => get().configure({ active }),
      updateItem: (id, patch) => {
        const { base, layers } = get()
        commit(
          patchConfig(base, id, patch),
          layers.map((layer) => ({
            ...layer,
            config: patchConfig(layer.config, id, patch),
          }))
        )
      },
      setLayer: (id, layerOrder, config) => {
        const { base, layers } = get()
        const rest = layers.filter((layer) => layer.id !== id)
        commit(
          base,
          config
            ? [...rest, { id, order: layerOrder, config }].sort(
                (a, b) => a.order - b.order
              )
            : rest
        )
      },
      nextOrder: () => ++order,
      registerSlot: (name, element) => {
        set((state) => ({
          slots: {
            ...state.slots,
            [name]: [...(state.slots[name] ?? []), element],
          },
        }))
        return () =>
          set((state) => ({
            slots: {
              ...state.slots,
              [name]: (state.slots[name] ?? []).filter(
                (target) => target !== element
              ),
            },
          }))
      },
    }
  })
}

/** Merges `next` into `base` part by part (rail, sidebar, header, active). */
function resolveShellConfig(base: ShellConfig, next: ShellConfig): ShellConfig {
  return {
    rail: { ...base.rail, ...defined(next.rail) },
    sidebar: { ...base.sidebar, ...defined(next.sidebar) },
    header: { ...base.header, ...defined(next.header) },
    active: { ...base.active, ...defined(next.active) },
  }
}

export const {
  Provider: ShellStoreProvider,
  useStore: useShellStore,
  useStoreApi: useShellStoreApi,
} = createContextStore(createShellStore, { name: "Shell" })

/* -------------------------------------------------------------------------- */
/* Hooks                                                                      */
/* -------------------------------------------------------------------------- */

/** Reads the shell as displayed: `useShell((shell) => shell.header.title)`. */
export function useShell<T>(selector: (shell: ResolvedShell) => T): T {
  return useShellStore((state) => selector(state.shell))
}

/**
 * Changes the shell from anywhere, and the changes stay when the page
 * changes: `configure` (rail, sidebar, header, active), `setActive`,
 * `updateItem(id, { meta: 3 })` for live counts.
 */
export function useShellApi() {
  const api = useShellStoreApi()
  return React.useMemo(() => {
    const { configure, setActive, updateItem } = api.getState()
    return { configure, setActive, updateItem }
  }, [api])
}

const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

// A string that changes when the config's data changes. Functions compare as
// equal (the latest ones are always called), elements by type, key and props.
function signatureOf(config: ShellConfig) {
  return JSON.stringify(config, (_, value: unknown) => {
    if (typeof value === "function") return "ƒ"
    if (React.isValidElement(value)) {
      const type = value.type as
        string | { displayName?: string; name?: string }
      return {
        element:
          typeof type === "string" ? type : (type.displayName ?? type.name),
        key: value.key,
        props: value.props,
      }
    }
    return value
  })
}

// Swaps every function for one that calls the latest version at that path,
// so handlers stay fresh without re-publishing the layer on every render.
function bindLatest<T>(
  value: T,
  latest: () => unknown,
  path: (string | number)[] = []
): T {
  if (typeof value === "function") {
    return ((...args: unknown[]) => {
      const current = path.reduce<unknown>(
        (node, key) =>
          (node as Record<string | number, unknown> | undefined)?.[key],
        latest()
      )
      return typeof current === "function" ? current(...args) : undefined
    }) as T
  }
  if (
    React.isValidElement(value) ||
    value === null ||
    typeof value !== "object"
  )
    return value
  if (Array.isArray(value)) {
    return value.map((entry, index) =>
      bindLatest(entry, latest, [...path, index])
    ) as T
  }
  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [
      key,
      bindLatest(entry, latest, [...path, key]),
    ])
  ) as T
}

/**
 * What the shell shows while this component is mounted: its rail, sidebar
 * sub nav, header and active items, over the base config. Call it in a page
 * (or a layout); when the page unmounts the shell goes back. Deeper
 * components win over their parents, and later pages over earlier ones.
 *
 * ```tsx
 * useShellPage({
 *   header: { title: "All tasks", breadcrumbs: [{ label: "Tasks", href: "/tasks" }] },
 *   sidebar: { sections: taskSections },
 *   active: { sidebar: "all" },
 * })
 * ```
 */
export function useShellPage(config: ShellConfig) {
  const api = useShellStoreApi()
  const id = React.useId()
  const [order] = React.useState(() => api.getState().nextOrder())
  const latest = React.useRef(config)
  const signature = signatureOf(config)

  useIsomorphicLayoutEffect(() => {
    latest.current = config
  })
  useIsomorphicLayoutEffect(() => {
    api.getState().setLayer(
      id,
      order,
      bindLatest(latest.current, () => latest.current)
    )
  }, [api, id, order, signature])
  useIsomorphicLayoutEffect(
    () => () => api.getState().setLayer(id, order, null),
    [api, id, order]
  )
}

/* -------------------------------------------------------------------------- */
/* Active items                                                               */
/* -------------------------------------------------------------------------- */

const matchesPath = (href: string | undefined, path: string | undefined) =>
  href !== undefined &&
  path !== undefined &&
  (path === href || path.startsWith(href.endsWith("/") ? href : `${href}/`))

/** The id of the item whose `href` is the longest match for `path`. */
export function matchActive(
  items: readonly ShellNavItem[],
  path: string | undefined
): string | undefined {
  let best: { id: string; length: number } | undefined
  const visit = (list: readonly ShellNavItem[]) => {
    for (const item of list) {
      if (
        matchesPath(item.href, path) &&
        (!best || item.href!.length > best.length)
      ) {
        best = { id: item.id, length: item.href!.length }
      }
      if (item.items) visit(item.items)
    }
  }
  visit(items)
  return best?.id
}

import * as React from "react"
import { createPortal } from "react-dom"
import { createStore, useStore, type StoreApi } from "zustand"

import {
  AppShell,
  MainPanel,
  PageContent,
  SkipLink,
  Topbar,
  TopbarActions,
  TopbarBreadcrumb,
  TopbarCrumb,
  TopbarCrumbSeparator,
  TopbarPage,
} from "@/components/forge/app-shell"
import {
  AppMark,
  IconRail,
  RailButton,
  RailFooter,
  RailNav,
} from "@/components/forge/icon-rail"
import {
  NavItem,
  NavSectionHeading,
  SidebarBrand,
  SidebarSection,
  SubNav,
  WorkspaceSidebar,
} from "@/components/forge/workspace-sidebar"
import {
  checkAccess,
  UserAccessContext,
  type UserAccessState,
} from "@/lib/user-access"

import {
  matchActive,
  ShellStoreProvider,
  useShellPage,
  useShellStore,
  useShellStoreApi,
  type ShellConfig,
  type ShellCrumb,
  type ShellLinkRenderer,
  type ShellNavItem,
  type ShellSlotName,
} from "./shell-store"

/* -------------------------------------------------------------------------- */
/* Provider                                                                   */
/* -------------------------------------------------------------------------- */

export type ShellProviderProps = {
  children?: React.ReactNode
  /** The rail, sidebar sub nav and header before any page changes them. */
  initial?: ShellConfig
  /**
   * The current route's path. Rail and sidebar items whose `href` matches
   * (exactly, or as a parent path) are active unless a page says otherwise.
   */
  currentPath?: string
  /**
   * Client-side navigation for items and crumbs with an `href`, e.g. your
   * router's `navigate`. Without it they render as links.
   */
  navigate?: (href: string) => void
  /** Renders `href`s with your router's link: `(href) => <Link to={href} />`. */
  renderLink?: ShellLinkRenderer
}

function SyncRouting({
  currentPath,
  navigate,
  renderLink,
}: Pick<ShellProviderProps, "currentPath" | "navigate" | "renderLink">) {
  const api = useShellStoreApi()
  React.useLayoutEffect(() => {
    api.setState({ currentPath, navigate, renderLink })
  }, [api, currentPath, navigate, renderLink])
  return null
}

/**
 * Holds what the app shell shows — the icon rail, the sidebar sub nav and
 * the header — so pages can change it. Put it above `ShellLayout`; pages
 * use `useShellPage` / `ShellPage`, anything else `useShellApi`.
 */
export function ShellProvider({
  children,
  initial,
  currentPath,
  navigate,
  renderLink,
}: ShellProviderProps) {
  return (
    <ShellStoreProvider
      initial={{ initial, currentPath, navigate, renderLink }}
    >
      <SyncRouting
        currentPath={currentPath}
        navigate={navigate}
        renderLink={renderLink}
      />
      {children}
    </ShellStoreProvider>
  )
}

/* -------------------------------------------------------------------------- */
/* Slots                                                                      */
/* -------------------------------------------------------------------------- */

function SlotOutlet({ name }: { name: ShellSlotName }) {
  const register = useShellStore((state) => state.registerSlot)
  const ref = React.useCallback(
    (element: HTMLDivElement | null) =>
      element ? register(name, element) : undefined,
    [register, name]
  )
  return <div ref={ref} data-slot={`shell-${name}`} className="contents" />
}

/**
 * Renders its children in a region of the shell, from anywhere below
 * `ShellLayout` — with the page's own state and handlers.
 */
export function ShellSlot({
  name,
  children,
}: {
  name: ShellSlotName
  children?: React.ReactNode
}) {
  const target = useShellStore((state) => state.slots[name]?.at(-1))
  return target ? createPortal(children, target) : null
}

/** The page's buttons in the top bar, right-aligned. */
export function ShellHeaderActions({
  children,
}: {
  children?: React.ReactNode
}) {
  return <ShellSlot name="header-actions">{children}</ShellSlot>
}

/** A `ViewToolbar` (tabs, filters) between the top bar and the content. */
export function ShellToolbar({ children }: { children?: React.ReactNode }) {
  return <ShellSlot name="toolbar">{children}</ShellSlot>
}

/** A `WorkspaceFooter` under the content. */
export function ShellFooter({ children }: { children?: React.ReactNode }) {
  return <ShellSlot name="footer">{children}</ShellSlot>
}

/** Sidebar content above the sections, e.g. `CommandButton` or a switcher. */
export function ShellSidebarTop({ children }: { children?: React.ReactNode }) {
  return <ShellSlot name="sidebar-top">{children}</ShellSlot>
}

/** Sidebar content below the sections, e.g. `SidebarStatus`. */
export function ShellSidebarBottom({
  children,
}: {
  children?: React.ReactNode
}) {
  return <ShellSlot name="sidebar-bottom">{children}</ShellSlot>
}

/* -------------------------------------------------------------------------- */
/* Pages                                                                      */
/* -------------------------------------------------------------------------- */

/** `useShellPage` as an element: the shell shows this while it's mounted. */
export function ShellPage(config: ShellConfig) {
  useShellPage(config)
  return null
}

/* -------------------------------------------------------------------------- */
/* Rendering                                                                  */
/* -------------------------------------------------------------------------- */

// Without a UserAccessProvider there's nothing to check, so nothing hides.
const noAccess = createStore<UserAccessState | null>(() => null)

function useItemFilter() {
  const store = React.useContext(
    UserAccessContext
  ) as StoreApi<UserAccessState | null> | null
  const access = useStore(store ?? noAccess, (state) => state)
  return React.useCallback(
    function filter(items: readonly ShellNavItem[]): ShellNavItem[] {
      return items
        .filter((item) => {
          if (!item.permission && !item.role) return true
          if (!store || !access) return true
          return (
            access.status === "ready" &&
            checkAccess(access, {
              permission: item.permission,
              role: item.role,
            })
          )
        })
        .map((item) =>
          item.items ? { ...item, items: filter(item.items) } : item
        )
    },
    [store, access]
  )
}

type Routing = {
  navigate: ((href: string) => void) | undefined
  renderLink: ShellLinkRenderer | undefined
}

/** Props that make a control go to `href`: a click handler or a link. */
function linkProps(
  target: { href?: string; onSelect?: () => void },
  { navigate, renderLink }: Routing
) {
  const onClick = () => {
    target.onSelect?.()
    if (target.href && navigate) navigate(target.href)
  }
  if (!target.href || navigate) return { onClick }
  return {
    onClick,
    render: renderLink ? renderLink(target.href) : <a href={target.href} />,
  }
}

function ShellNavItems({
  items,
  activeId,
  routing,
  size,
}: {
  items: readonly ShellNavItem[]
  activeId: string | undefined
  routing: Routing
  size?: "default" | "sm"
}) {
  return items.map((item) => (
    <React.Fragment key={item.id}>
      <NavItem
        icon={item.icon}
        active={item.id === activeId}
        meta={item.meta}
        size={size}
        {...linkProps(item, routing)}
      >
        {item.label}
      </NavItem>
      {item.items && item.items.length > 0 && (
        <SubNav>
          <ShellNavItems
            items={item.items}
            activeId={activeId}
            routing={routing}
            size="sm"
          />
        </SubNav>
      )}
    </React.Fragment>
  ))
}

function ShellRailButton({
  item,
  active,
  routing,
}: {
  item: ShellNavItem
  active: boolean
  routing: Routing
}) {
  const { render, onClick } = linkProps(item, routing)
  return (
    <RailButton
      icon={item.icon ?? "layers"}
      label={item.label}
      active={active}
      onClick={onClick}
      {...(render && { render, nativeButton: false })}
    />
  )
}

function Crumb({ crumb, routing }: { crumb: ShellCrumb; routing: Routing }) {
  return (
    <>
      <TopbarCrumb
        icon={crumb.icon}
        onClick={() => {
          crumb.onSelect?.()
          if (!crumb.href) return
          if (routing.navigate) routing.navigate(crumb.href)
          else window.location.assign(crumb.href)
        }}
      >
        {crumb.label}
      </TopbarCrumb>
      <TopbarCrumbSeparator />
    </>
  )
}

export type ShellLayoutProps = {
  /** The page. Rendered in the scrolling `PageContent` (see `bare`). */
  children?: React.ReactNode
  /** The sidebar's brand row, e.g. orb, name and collapse button. */
  brand?: React.ReactNode
  /** The rail's top mark. Default: `AppMark`, going to the first rail item. */
  mark?: React.ReactNode
  /** Render the page without `PageContent`, for pages with their own scroll region. */
  bare?: boolean
  /** Classes for `AppShell` (e.g. `h-[640px]` to embed it). */
  className?: string
}

/**
 * The Forge app shell drawn from `ShellProvider`: icon rail, sidebar sub nav
 * with its sections, and the top bar with breadcrumbs, the page title and
 * the page's actions. Active items follow the current path; items with a
 * `permission` or `role` hide for users without it.
 */
export function ShellLayout({
  children,
  brand,
  mark,
  bare = false,
  className,
}: ShellLayoutProps) {
  const shell = useShellStore((state) => state.shell)
  const currentPath = useShellStore((state) => state.currentPath)
  const navigate = useShellStore((state) => state.navigate)
  const renderLink = useShellStore((state) => state.renderLink)
  const routing = React.useMemo(
    () => ({ navigate, renderLink }),
    [navigate, renderLink]
  )
  const filter = useItemFilter()

  const railItems = filter(shell.rail.items)
  const railFooter = filter(shell.rail.footer)
  const activeRail =
    shell.active.rail ?? matchActive([...railItems, ...railFooter], currentPath)
  const sections = shell.sidebar.sections
    .map((section) => ({ ...section, items: filter(section.items) }))
    .filter((section) => section.items.length > 0)
  const activeSidebar =
    shell.active.sidebar ??
    matchActive(
      sections.flatMap((section) => section.items),
      currentPath
    )
  const sidebarHidden = shell.sidebar.hidden
  const { title, icon, breadcrumbs } = shell.header

  return (
    <AppShell className={className}>
      <SkipLink href="#content">Skip to content</SkipLink>
      <IconRail>
        {mark ?? (
          <AppMark
            aria-label={railItems[0]?.label ?? "Home"}
            onClick={() => {
              const home = railItems[0]
              home?.onSelect?.()
              if (!home?.href) return
              if (navigate) navigate(home.href)
              else window.location.assign(home.href)
            }}
          />
        )}
        <RailNav aria-label="Sections">
          {railItems.map((item) => (
            <ShellRailButton
              key={item.id}
              item={item}
              active={item.id === activeRail}
              routing={routing}
            />
          ))}
        </RailNav>
        {railFooter.length > 0 && (
          <RailFooter>
            {railFooter.map((item) => (
              <ShellRailButton
                key={item.id}
                item={item}
                active={item.id === activeRail}
                routing={routing}
              />
            ))}
          </RailFooter>
        )}
      </IconRail>
      <WorkspaceSidebar
        label={shell.sidebar.label ?? "Navigation"}
        // A hidden sub nav still backs the mobile menu, for the rail's items.
        className={sidebarHidden ? "hidden" : undefined}
      >
        {brand && <SidebarBrand>{brand}</SidebarBrand>}
        <SlotOutlet name="sidebar-top" />
        {railItems.length > 0 && (
          // The rail hides on phones; its items lead the mobile menu instead.
          <SidebarSection
            variant="primary"
            className={sidebarHidden ? undefined : "hidden max-[600px]:block"}
          >
            <ShellNavItems
              items={[...railItems, ...railFooter]}
              activeId={activeRail}
              routing={routing}
            />
          </SidebarSection>
        )}
        {!sidebarHidden &&
          sections.map((section, index) => (
            <SidebarSection
              key={section.id}
              variant={
                section.variant ??
                (index === sections.length - 1 ? "flush" : "default")
              }
            >
              {section.title && (
                <NavSectionHeading action={section.action}>
                  {section.title}
                </NavSectionHeading>
              )}
              <ShellNavItems
                items={section.items}
                activeId={activeSidebar}
                routing={routing}
              />
            </SidebarSection>
          ))}
        <SlotOutlet name="sidebar-bottom" />
      </WorkspaceSidebar>
      <MainPanel>
        <Topbar>
          <TopbarBreadcrumb>
            {breadcrumbs.map((crumb, index) => (
              <Crumb key={crumb.id ?? index} crumb={crumb} routing={routing} />
            ))}
            {title && <TopbarPage icon={icon}>{title}</TopbarPage>}
          </TopbarBreadcrumb>
          <TopbarActions>
            <SlotOutlet name="header-actions" />
          </TopbarActions>
        </Topbar>
        <SlotOutlet name="toolbar" />
        {bare ? children : <PageContent id="content">{children}</PageContent>}
        <SlotOutlet name="footer" />
      </MainPanel>
    </AppShell>
  )
}
